//! Compare synthetic source descriptor enumeration and selected writers.
use spore_core::cell_food_descriptor_order_v1::{enumerate,write_selected,Descriptor};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut args=std::env::args().skip(1);let b=std::fs::read(args.next().expect("native rows")).unwrap();let map=std::fs::read_to_string(args.next().expect("host map")).unwrap();assert_eq!(b.len(),192);let symbol=|name:&str|{let v:Vec<_>=map.lines().filter(|l|l.split_whitespace().nth(1)==Some(name)).collect();assert_eq!(v.len(),1);u32::from_str_radix(v[0].split_whitespace().nth(2).unwrap(),16).unwrap()};let d=symbol("Descriptors");let base=symbol("ObjectA");let row=|identity,key,offset,valid|Descriptor{identity,key,offset,base:0,has_read:valid,has_write:valid};let rows=[row(d,0xabcd0000,0x10,true),row(d+0x3c,0xabcd0001,0x1c,true),row(d+0x78,0xabcd0011,0x20,true),row(d+0xb4,0,0,false)];let entries=enumerate(&rows,true).unwrap();assert_eq!(entries.iter().map(|e|(e.key,e.descriptor)).collect::<Vec<_>>(),vec![(0xabcd0000,d),(0xabcd0001,d+0x3c),(0xabcd0011,d+0x78)]);
 for i in 0..4{let v=(i%2) as u32;let bytes=write_selected(&rows[1..3],base,&[v,v+1000],true).unwrap();let r=&b[i*48..(i+1)*48];assert_eq!((w(r,0),w(r,4),w(r,8),w(r,12),w(r,16),w(r,20)),(1,3,u32::from_le_bytes(bytes[0..4].try_into().unwrap()),u32::from_le_bytes(bytes[4..8].try_into().unwrap()),2,4));let fp=w(r,24);assert_eq!(fp&0xffff,if i>=2{0x37f}else{0x27f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,28)&!0x3f,0x1f80);assert_eq!((w(r,32),w(r,36),w(r,40),w(r,44)),(2,2,0xc0dec0de,0xa5a5a5a5));}println!("matched four synthetic descriptor enumeration/food-order rows; outer writer and files excluded");}
